public enum Cell { Empty, X, O }
public enum Player { X, O }

public class Board
{
    private readonly Cell[,] _cells;
    public int Size { get; }

    public Board(int size = 3) { _cells = new Cell[size, size]; Size = size; }

    public bool Place(int row, int col, Player player)
    {
        if (_cells[row, col] != Cell.Empty) return false;
        _cells[row, col] = player == Player.X ? Cell.X : Cell.O;
        return true;
    }

    public Player? CheckWinner()
    {
        // Rows, columns, diagonals
        for (int i = 0; i < Size; i++)
        {
            if (_cells[i, 0] != Cell.Empty && Enumerable.Range(0, Size - 1).All(j => _cells[i, j] == _cells[i, j + 1]))
                return _cells[i, 0] == Cell.X ? Player.X : Player.O;
            if (_cells[0, i] != Cell.Empty && Enumerable.Range(0, Size - 1).All(j => _cells[j, i] == _cells[j + 1, i]))
                return _cells[0, i] == Cell.X ? Player.X : Player.O;
        }
        if (_cells[0, 0] != Cell.Empty && Enumerable.Range(0, Size - 1).All(i => _cells[i, i] == _cells[i + 1, i + 1]))
            return _cells[0, 0] == Cell.X ? Player.X : Player.O;
        if (_cells[0, Size - 1] != Cell.Empty && Enumerable.Range(0, Size - 1).All(i => _cells[i, Size - 1 - i] == _cells[i + 1, Size - 2 - i]))
            return _cells[0, Size - 1] == Cell.X ? Player.X : Player.O;
        return null;
    }

    public bool IsFull => _cells.Cast<Cell>().All(c => c != Cell.Empty);
}

public class Game
{
    public Board Board { get; } = new();
    public Player CurrentPlayer { get; private set; } = Player.X;
    public Player? Winner { get; private set; }
    public bool IsDraw => Winner == null && Board.IsFull;

    public bool Play(int row, int col)
    {
        if (Winner != null || !Board.Place(row, col, CurrentPlayer)) return false;
        Winner = Board.CheckWinner();
        if (Winner == null && !Board.IsFull)
            CurrentPlayer = CurrentPlayer == Player.X ? Player.O : Player.X;
        return true;
    }
}
